// hypdfs.cpp -- [F] exact avoider search (all proper patterns, Lemma H windows) for ONE explicit all-odd run datum
// (c5, task OlsonRunCount5, target T4: the c3 "hyp" words, regenerated by c5/map5.cpp).  Independent of c2/famdfs (which
// handles all-singleton words only): general runs (a_t letters rho_1, b_t letters rho_(-1)), d_t = a_t - b_t,
// B = sum b_t, H = sum floor(l_t/2), kappa = p - 1 - H, beta(Q) = number of EVEN boundary reflection runs of Q (computed,
// = 0 for all-odd words).  lambda(Q) = min(p - m + 1, D_Q + B - kappa + m - beta, floor((D_Q + B)/2) + 1) - shrink;
// window I(Q) = [1 - lambda(Q^c), lambda(Q) - 1].  u_0..u_(k-2) searched, u_(k-1) = -sum; every proper pattern not
// containing run k-1 is checked (its complement has the negated residue and the negated window).
// Usage: hypdfs p a0,a1,... b0,b1,... l0,l1,... [shrink]
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cstdint>
#include <vector>
#include <string>
static int p, k, B, kappa, shrink;
static int a[64], b[64], l[64], d[64];
static uint32_t FULL;
static std::vector<uint64_t> forb;
static std::vector<uint8_t> sums;
static int u[64];
static long long checks = 0;
static int fl2(int x) { return x >= 0 ? x / 2 : -((-x + 1) / 2); }
static int lam(uint32_t Q) {
    int m = 0, D = 0, beta = 0;
    for (int t = 0; t < k; t++) {
        bool in = (Q >> t) & 1u, prev = (Q >> ((t + k - 1) % k)) & 1u;
        if (in) D += d[t];
        if (in && !prev) m++;
        // reflection run S_(t-1) sits between runs t-1 and t; it is a boundary run iff exactly one of them is in Q
        if (in != prev && l[(t + k - 1) % k] % 2 == 0) beta++;
    }
    int x = p - m + 1, y = D + B - kappa + m - beta, z = fl2(D + B) + 1;
    int v = x < y ? x : y; v = v < z ? v : z;
    return v - shrink;
}
static bool dfs(int j) {
    if (j == k - 1) return true;
    uint32_t bit = 1u << j;
    for (int v = 0; v < p; v++) {
        bool ok = true;
        for (uint32_t P = 0; P < bit; P++) {
            checks++;
            int s = sums[P] + v; if (s >= p) s -= p;
            uint32_t Q = P | bit;
            if ((forb[Q] >> s) & 1ull) { ok = false; break; }
            sums[Q] = (uint8_t)s;
        }
        if (!ok) continue;
        u[j] = v;
        if (dfs(j + 1)) return true;
    }
    return false;
}
static int parse(const char* s, int* out) { int n = 0; std::string t(s); size_t i = 0; while (i < t.size()) { size_t j = t.find(',', i); if (j == std::string::npos) j = t.size(); out[n++] = atoi(t.substr(i, j - i).c_str()); i = j + 1; } return n; }
int main(int argc, char** argv) {
    if (argc < 5) return 1;
    p = atoi(argv[1]); k = parse(argv[2], a); parse(argv[3], b); parse(argv[4], l);
    shrink = argc > 5 ? atoi(argv[5]) : 0;
    if (p > 63 || k > 30) { printf("{\"error\":\"size\"}\n"); return 1; }
    int A = 0, H = 0, R = 0, odd = 1; B = 0;
    for (int t = 0; t < k; t++) { d[t] = a[t] - b[t]; A += a[t]; B += b[t]; H += l[t] / 2; R += a[t] + b[t]; if (l[t] % 2 == 0) odd = 0; }
    int F = 0; for (int t = 0; t < k; t++) F += l[t];
    kappa = p - 1 - H;
    FULL = (1u << k) - 1;
    size_t n = (size_t)1 << (k - 1);
    forb.assign(n, 0); sums.assign(n, 0);
    for (size_t Q = 1; Q < n; Q++) {
        int lo = 1 - lam(FULL ^ (uint32_t)Q), hi = lam((uint32_t)Q) - 1;
        uint64_t msk = 0;
        if (hi - lo + 1 >= p) msk = (p == 64) ? ~0ull : ((1ull << p) - 1);
        else for (int x = lo; x <= hi; x++) msk |= 1ull << (((x % p) + p) % p);
        forb[Q] = msk;
    }
    // empty-pattern condition (Lemma H): A, B <= 2p - 1 and min(A, B) <= kappa
    bool emptykill = !(A <= 2 * p - 1 && B <= 2 * p - 1 && (A < B ? A : B) <= kappa);
    bool found = emptykill ? false : dfs(0);
    printf("{\"p\":%d,\"k\":%d,\"A\":%d,\"B\":%d,\"R\":%d,\"F\":%d,\"len\":%d,\"kappa\":%d,\"kB\":%d,\"all_odd\":%d,\"shrink\":%d,\"empty_kills\":%d,\"avoider\":%s,\"checks\":%lld,\"u\":[",
           p, k, A, B, R, F, R + F, kappa, kappa - B, odd, shrink, (int)emptykill, found ? "true" : "false", checks);
    if (found) { int s = 0; for (int j = 0; j < k - 1; j++) { printf("%s%d", j ? "," : "", u[j]); s += u[j]; } printf(",%d", ((-s) % p + p) % p); }
    printf("]}\n");
    return 0;
}
